-- Thousand Needles: creature abilities
-- Most of the zone's creatures (the Grimtotem, the Twilight's Hammer, the pirates and Venture Co. of the flooded Needles, the wildlife) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '4117,4118,5933,5934,5935,5937,14426,14427,39947,39951,40061,40062,40063,40092,40432,40449,40959,41076,41081,41082,41131,41196,41199,41421,41431,41439,41444,41458,45381,45383,45385,45438,47388,47389,47390,47487,47528,47583,47585,47602,47619,47620,47630,47804,47816,48130,48132,48138,48177,48178,48179';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '7895,47763,47766,47777,48131,48155';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
